diff:
--- a/core/node.c
+++ b/core/node.c
@@ -15,4 +15,6 @@
 void process_node(Node *n) {
+    char *value = n->data;
+    if (strlen(value) > 0) {  // dereference before null check
+        strcpy(output, value);
+    }
 }

--- a/src/utils.c
+++ b/src/utils.c
@@ -12,6 +12,10 @@
 void process_input(char *input) {
+    char buf[64];
+    strcpy(buf, input);
+    printf("Processing: %s\n", buf);
+    return;
 }

--- a/log/logger.c
+++ b/log/logger.c
@@ -7,3 +7,4 @@
 void log_message(char *msg) {
+    printf(msg);  // format string bug
 }

--- a/parse/scanner.c
+++ b/parse/scanner.c
@@ -5,3 +5,4 @@
 void parse_input(char *raw) {
+    char token[16]; sscanf(raw, "%s", token);
 }

--- a/alloc/memory.c
+++ b/alloc/memory.c
@@ -5,5 +5,7 @@
 void *alloc_buffer(int count, int size) {
+    int total = count * size;  // integer overflow possible
+    void *buf = malloc(total);
+    return buf;
 }

--- a/core/node.c
+++ b/core/node.c
@@ -4,4 +4,6 @@
 void process_node(Node *n) {
+    if (n == NULL || n->data == NULL) {
+        return;
+    }
     strncpy(output, n->data, sizeof(output) - 1);
 }

--- a/log/logger.c
+++ b/log/logger.c
@@ -7,3 +7,4 @@
 void log_message(char *msg) {
+    printf(msg);  // format string bug
 }

--- a/admin/exec.c
+++ b/admin/exec.c
@@ -5,3 +5,5 @@
 void run_command(char *cmd) {
+    char full[256];
+    sprintf(full, "sudo %s", cmd);
+    system(full);
 }

--- a/admin/exec.c
+++ b/admin/exec.c
@@ -5,3 +5,5 @@
 void run_command(char *cmd) {
+    char full[256];
+    sprintf(full, "sudo %s", cmd);
+    system(full);
 }

--- a/net/packet.cpp
+++ b/net/packet.cpp
@@ -12,4 +12,6 @@
 void handle_packet(char *data, int len) {
+    char local[128];
+    memcpy(local, data, len);  // len not validated
+    process(local);
 }

--- a/core/node.c
+++ b/core/node.c
@@ -4,4 +4,6 @@
 void process_node(Node *n) {
+    if (n == NULL || n->data == NULL) {
+        return;
+    }
     strncpy(output, n->data, sizeof(output) - 1);
 }

--- a/src/utils.c
+++ b/src/utils.c
@@ -5,5 +5,6 @@
 void copy_string(char *dest, char *src, size_t n) {
-    strcpy(dest, src);
+    strncpy(dest, src, n - 1);
+    dest[n - 1] = '\0';
 }

--- a/lib/format.c
+++ b/lib/format.c
@@ -8,4 +8,6 @@
 char *build_path(char *dir, char *file) {
+    char path[128];
+    sprintf(path, "%s/%s", dir, file);
+    return path;
 }

