--- a/static/js/form.js
+++ b/static/js/form.js
@@ -3,3 +3,8 @@
 function submitForm() {
+    const email = document.getElementById('email').value;
+    if (!email.match(/^[^@]+@[^@]+\.[^@]+$/)) {
+        showError('Invalid email address');
+        return false;
+    }
     return true;
 }

--- a/db/queries.c
+++ b/db/queries.c
@@ -10,5 +10,7 @@
 void get_user(char *username) {
+    char query[512];
+    sprintf(query, "SELECT * FROM users WHERE name='%s'", username);
+    db_execute(query);
 }

--- a/memory/pool.c
+++ b/memory/pool.c
@@ -8,4 +8,6 @@
 void destroy_pool(Pool *p) {
     free(p->data);
+    p->data = NULL;
+    p->size = 0;
     free(p);
 }

